const entries = [
  { id: 'birads', term: 'BI-RADS', clinical: 'A standard breast-imaging reporting framework', aliases: ['bi rads', 'birads', 'category', 'assessment'], summary: 'A standard way radiologists describe mammogram findings and their assessment.', explanation: 'BI-RADS is a reporting system created by the American College of Radiology. It gives imaging findings a category so that reports can be described consistently. A category is not, by itself, a diagnosis and does not explain what any result means for one person.', questions: ['What does this category mean in the context of my report?', 'Is there anything in my history or prior images that affects how you view this result?'], source: 'American College of Radiology — BI-RADS Atlas', url: 'https://www.acr.org/Clinical-Resources/Reporting-and-Data-Systems/Bi-Rads', reviewed: '2026-10-15' },
  { id: 'birads-0', term: 'BI-RADS 0', clinical: 'Assessment pending more information', aliases: ['0', 'birads 0', 'bi-rads 0', 'incomplete'], summary: 'The imaging review is not complete yet; more information may be needed.', explanation: 'This category means the radiologist needs more information before completing the assessment. That can include extra views or comparison with earlier images. It does not tell you whether you do or do not have cancer.', questions: ['What information or imaging is needed to complete the assessment?', 'Can you explain the timeline for getting the additional information?'], source: 'American Cancer Society — Mammogram report terminology', url: 'https://www.cancer.org/cancer/types/breast-cancer/screening-tests-and-early-detection/mammograms/understanding-your-mammogram-report.html', reviewed: '2026-11-07' },
  { id: 'birads-1', term: 'BI-RADS 1', clinical: 'No suspicious image finding recorded', aliases: ['1', 'birads 1', 'bi-rads 1', 'negative'], summary: 'No concerning finding is described in the imaging assessment.', explanation: 'In BI-RADS terminology, “negative” means no suspicious finding is described on the imaging exam. It is an imaging assessment, not an all-purpose statement about a person’s health or future risk.', questions: ['How does this result fit with my personal screening plan?'], source: 'American Cancer Society — Mammogram report terminology', url: 'https://www.cancer.org/cancer/types/breast-cancer/screening-tests-and-early-detection/mammograms/understanding-your-mammogram-report.html', reviewed: '2026-11-07' },
  { id: 'birads-2', term: 'BI-RADS 2', clinical: 'A noncancerous imaging finding recorded', aliases: ['2', 'birads 2', 'bi-rads 2', 'benign'], summary: 'A finding is described as noncancerous in the imaging assessment.', explanation: '“Benign” is the word used for a finding that is not cancer. The report may name the type of finding. Your clinician can help place this information alongside your history and any symptoms.', questions: ['What benign finding is described in my report?', 'Does this change anything I should discuss with my clinician?'], source: 'American Cancer Society — Mammogram report terminology', url: 'https://www.cancer.org/cancer/types/breast-cancer/screening-tests-and-early-detection/mammograms/understanding-your-mammogram-report.html', reviewed: '2026-11-07' },
  { id: 'birads-3', term: 'BI-RADS 3', clinical: 'Finding assessed as likely noncancerous', aliases: ['3', 'birads 3', 'bi-rads 3', 'probably benign'], summary: 'The radiologist describes a finding as probably benign, using a standard category.', explanation: 'This category is used for a finding the radiologist assesses as probably benign. It does not replace a conversation about the particular report, health history, or the appropriate next step for an individual.', questions: ['What characteristics led to this assessment?', 'What follow-up, if any, are you recommending for my situation?'], source: 'American Cancer Society — Mammogram report terminology', url: 'https://www.cancer.org/cancer/types/breast-cancer/screening-tests-and-early-detection/mammograms/understanding-your-mammogram-report.html', reviewed: '2026-11-07' },
  { id: 'density', term: 'Breast density', clinical: 'Breast tissue composition on a mammogram', aliases: ['dense breasts', 'dense breast tissue', 'density', 'heterogeneously dense', 'extremely dense'], summary: 'A description of how breast tissue appears on a mammogram—not how breasts look or feel.', explanation: 'Breast density describes the mix of fibrous and glandular tissue compared with fatty tissue as it appears on a mammogram. Dense tissue can make some cancers harder to see on a mammogram. It is common, and it is not a diagnosis. Recommendations about supplemental screening can differ; evidence and guidance do not point to one option that is right for everyone.', questions: ['What density category is in my report?', 'How does my density relate to my own history and risk factors?', 'Can we discuss the possible benefits and harms of any additional imaging for me?'], source: 'National Cancer Institute — Dense Breasts', url: 'https://www.cancer.gov/types/breast/screening/dense-breasts', reviewed: '2026-10-15' },
  { id: 'calcifications', term: 'Calcifications', clinical: 'Tiny calcium deposits seen on mammography', aliases: ['calcium', 'microcalcifications', 'macrocalcifications'], summary: 'Small calcium deposits that can appear in breast tissue on a mammogram.', explanation: 'Calcifications are small calcium deposits that can be seen on a mammogram. They are common. Their appearance and pattern help a radiologist describe them, but this glossary cannot interpret what a particular report means.', questions: ['What type or pattern of calcifications does my report describe?', 'Can you explain what that description means in my situation?'], source: 'American Cancer Society — Mammogram report terminology', url: 'https://www.cancer.org/cancer/types/breast-cancer/screening-tests-and-early-detection/mammograms/understanding-your-mammogram-report.html', reviewed: '2026-11-07' },
  { id: 'mass', term: 'Mass', clinical: 'A three-dimensional area seen on imaging', aliases: ['lump', 'lesion', 'nodule'], summary: 'A term radiologists may use for an area with a defined shape on imaging.', explanation: 'In breast imaging, a mass is an area seen in two different views that has a shape and borders that can be described. It is an imaging term. A report’s other details and a clinician’s assessment are needed to understand a specific finding.', questions: ['What features of the mass are described in my report?', 'What questions should I ask about this finding?'], source: 'American Cancer Society — Mammogram report terminology', url: 'https://www.cancer.org/cancer/types/breast-cancer/screening-tests-and-early-detection/mammograms/understanding-your-mammogram-report.html', reviewed: '2026-11-07' },
  { id: 'birads-4', term: 'BI-RADS 4', clinical: 'Imaging category for a suspicious finding', aliases: ['4', 'birads 4', 'bi-rads 4', 'suspicious abnormality'], summary: 'A standard assessment category for a finding the radiologist considers suspicious.', explanation: 'BI-RADS 4 is an imaging assessment category for a finding that needs more diagnostic evaluation. It communicates concern based on the images, but it is not itself a diagnosis and this glossary cannot say what it means for an individual.', questions: ['What imaging features are described in my report?', 'How can I discuss the assessment with the clinician caring for me?'], source: 'American Cancer Society — Understanding Your Mammogram Report', url: 'https://www.cancer.org/cancer/types/breast-cancer/screening-tests-and-early-detection/mammograms/understanding-your-mammogram-report.html', reviewed: '2026-11-07' },
  { id: 'birads-5', term: 'BI-RADS 5', clinical: 'Imaging category for a highly concerning finding', aliases: ['5', 'birads 5', 'bi-rads 5', 'highly suggestive'], summary: 'A standard assessment category for imaging features that are highly concerning.', explanation: 'BI-RADS 5 is an imaging assessment category used when the radiologist sees features that are highly concerning. It is not a diagnosis by itself; only the clinicians involved in a person’s care can explain the report alongside all other information.', questions: ['Which imaging features are noted in my report?', 'Who can explain how this assessment fits my situation?'], source: 'American Cancer Society — Understanding Your Mammogram Report', url: 'https://www.cancer.org/cancer/types/breast-cancer/screening-tests-and-early-detection/mammograms/understanding-your-mammogram-report.html', reviewed: '2026-11-07' },
  { id: 'birads-6', term: 'BI-RADS 6', clinical: 'Imaging category used after biopsy confirms cancer', aliases: ['6', 'birads 6', 'bi-rads 6', 'biopsy proven'], summary: 'A standard assessment category used when a breast cancer has already been confirmed by biopsy.', explanation: 'BI-RADS 6 is used for imaging of a breast finding that has already been shown to be cancer by a biopsy. The category refers to known prior pathology; it does not allow this glossary to explain an individual report or care plan.', questions: ['What prior pathology result is the report referring to?', 'Which clinician can explain the imaging report in the context of my care?'], source: 'American Cancer Society — Understanding Your Mammogram Report', url: 'https://www.cancer.org/cancer/types/breast-cancer/screening-tests-and-early-detection/mammograms/understanding-your-mammogram-report.html', reviewed: '2026-11-07' },
  { id: 'screening-mammogram', term: 'Screening mammogram', clinical: 'Mammography performed to look for changes before symptoms are present', aliases: ['screening', 'routine mammogram', 'screen mammogram'], summary: 'A mammogram performed to look for breast changes before a person has symptoms.', explanation: 'A screening mammogram is an x-ray exam used to look for breast changes in people who do not have symptoms. The word describes why the exam was performed, not what any particular image means.', questions: ['Was this exam described as screening or diagnostic?', 'Were prior images available for comparison?'], source: 'National Cancer Institute — Mammograms', url: 'https://www.cancer.gov/types/breast/screening/mammograms', reviewed: '2026-11-07' },
  { id: 'diagnostic-mammogram', term: 'Diagnostic mammogram', clinical: 'Mammography used to examine a specific concern or a screening finding', aliases: ['diagnostic', 'diagnostic imaging', 'diagnostic views'], summary: 'A mammogram designed to take a closer look at a concern or earlier finding.', explanation: 'A diagnostic mammogram is used when there is a specific question to examine, such as a symptom or a change seen on prior imaging. It may include additional images. The term describes the exam’s purpose, not a diagnosis.', questions: ['What question was this diagnostic exam intended to address?', 'Which part of the report describes the images taken?'], source: 'National Cancer Institute — Mammograms', url: 'https://www.cancer.gov/types/breast/screening/mammograms', reviewed: '2026-11-07' },
  { id: 'tomosynthesis', term: '3D mammography (tomosynthesis)', clinical: 'Digital breast tomosynthesis (DBT)', aliases: ['3d mammogram', 'dbt', 'digital breast tomosynthesis', 'tomosynthesis'], summary: 'A mammography method that uses multiple x-ray images to create a three-dimensional view.', explanation: 'Three-dimensional mammography, also called digital breast tomosynthesis or DBT, is a way of taking mammogram images. It describes the imaging method, not a finding or a diagnosis.', questions: ['Does my report identify 2D, 3D, or both types of mammography?', 'Is this wording describing the method or a finding?'], source: 'National Cancer Institute — Mammograms', url: 'https://www.cancer.gov/types/breast/screening/mammograms', reviewed: '2026-11-07' },
  { id: 'comparison', term: 'Comparison with prior images', clinical: 'Review alongside earlier mammograms', aliases: ['comparison', 'prior mammograms', 'previous images', 'comparison study'], summary: 'A note that earlier mammograms were used, or requested, when reviewing the current images.', explanation: 'Comparison means the reader considered, or wants to consider, earlier breast images alongside the current exam. It is a report process term and does not by itself say whether a finding is present or serious.', questions: ['Which prior exams were available for comparison?', 'Does the report describe a change or stability over time?'], source: 'American Cancer Society — Getting Called Back After a Mammogram', url: 'https://www.cancer.org/cancer/types/breast-cancer/screening-tests-and-early-detection/mammograms/getting-called-back-after-a-mammogram.html', reviewed: '2026-11-07' },
  { id: 'additional-views', term: 'Additional views', clinical: 'Extra mammogram images', aliases: ['additional imaging', 'spot compression', 'magnification views', 'extra views'], summary: 'Extra mammogram images taken to show an area from a different angle or in more detail.', explanation: 'Additional views are extra mammogram images that may be used to look more closely at an area. The phrase describes an imaging step; it does not tell you what an individual report ultimately means.', questions: ['Which additional views were taken?', 'Where does the report describe what was seen on those views?'], source: 'National Cancer Institute — Cancer Imaging Basics', url: 'https://dctd.cancer.gov/research/research-areas/imaging/basics', reviewed: '2026-11-07' },
  { id: 'asymmetry', term: 'Asymmetry', clinical: 'An area that appears different from corresponding breast tissue', aliases: ['asymmetric density', 'asymmetric tissue', 'asymmetric'], summary: 'A report term for breast tissue that looks different in one area or between the breasts.', explanation: 'Asymmetry is a word used when breast tissue looks different in one area or from the corresponding area in the other breast on a mammogram. The word alone does not identify the cause or explain an individual result.', questions: ['Which breast and area does the report describe?', 'Does the report say whether this appearance was compared with earlier images?'], source: 'American Cancer Society — Mammograms', url: 'https://www.cancer.org/cancer/types/breast-cancer/screening-tests-and-early-detection/mammograms.html', reviewed: '2026-11-07' },
  { id: 'architectural-distortion', term: 'Architectural distortion', clinical: 'Altered pattern of breast tissue on imaging', aliases: ['distortion', 'distorted structure', 'tissue distortion'], summary: 'A report term for breast tissue whose usual pattern appears pulled, changed, or disrupted on an image.', explanation: 'Architectural distortion describes an altered pattern of breast tissue on imaging. It is an observation in a report, not an explanation of why the pattern appears that way or a diagnosis for a particular person.', questions: ['What area and imaging description are included in my report?', 'Who can explain this observation alongside my full history and images?'], source: 'American Cancer Society — Mammograms', url: 'https://www.cancer.org/cancer/types/breast-cancer/screening-tests-and-early-detection/mammograms.html', reviewed: '2026-11-07' },
  { id: 'lymph-node', term: 'Lymph node', clinical: 'Small immune-system structure that may be visible on imaging', aliases: ['lymph nodes', 'axillary node', 'axillary lymph node'], summary: 'A small immune-system structure that can be seen in or near the breast on imaging.', explanation: 'Lymph nodes are small structures involved in the immune system. A mammogram report may mention a visible node or its location. That wording alone cannot explain what the image means for one person.', questions: ['Where does the report locate the lymph node?', 'What features does the report describe, if any?'], source: 'American Cancer Society — Understanding Your Mammogram Report', url: 'https://www.cancer.org/cancer/types/breast-cancer/screening-tests-and-early-detection/mammograms/understanding-your-mammogram-report.html', reviewed: '2026-11-07' },
  { id: 'breast-implant', term: 'Breast implant', clinical: 'Implant visible during mammography', aliases: ['implants', 'implant displaced views', 'implant displacement'], summary: 'A breast implant may be mentioned because it can affect how mammogram images are obtained or viewed.', explanation: 'A breast implant is a medical device that may be visible on a mammogram. The report may note it because special imaging techniques can be used to include as much breast tissue as possible. This term does not, by itself, describe an implant problem.', questions: ['Does the report describe any image limitations related to the implant?', 'Which clinician can explain the report in the context of my implant history?'], source: 'FDA — Mammography Quality Standards Act FAQ', url: 'https://www.fda.gov/radiation-emitting-products/mammography-information-patients/frequently-asked-questions-about-mammography-quality-standards-act-mqsa', reviewed: '2026-11-07' },
  { id: 'macrocalcifications', term: 'Macrocalcifications', clinical: 'Larger calcium deposits visible on a mammogram', aliases: ['macrocalcification', 'large calcifications'], summary: 'Larger calcium deposits that may appear in breast tissue on a mammogram.', explanation: 'Macrocalcifications are larger calcium deposits that can be seen on a mammogram. The word describes their size, not the cause of a particular finding or what it means for one person.', questions: ['Does my report describe the location or appearance of the calcifications?', 'Which clinician can explain this wording in my report?'], source: 'American Cancer Society — Mammograms', url: 'https://www.cancer.org/cancer/types/breast-cancer/screening-tests-and-early-detection/mammograms.html', reviewed: '2026-11-07' },
  { id: 'microcalcifications', term: 'Microcalcifications', clinical: 'Tiny calcium deposits visible on a mammogram', aliases: ['microcalcification', 'tiny calcifications'], summary: 'Very small calcium deposits that may appear as specks on a mammogram.', explanation: 'Microcalcifications are very small calcium deposits seen on a mammogram. The report’s full description and the surrounding imaging context matter; this glossary cannot interpret an individual pattern.', questions: ['What location and pattern does my report describe?', 'Who can explain the imaging wording in my situation?'], source: 'American Cancer Society — Mammograms', url: 'https://www.cancer.org/cancer/types/breast-cancer/screening-tests-and-early-detection/mammograms.html', reviewed: '2026-11-07' },
  { id: 'cyst', term: 'Cyst', clinical: 'Fluid-filled breast structure', aliases: ['cysts', 'simple cyst', 'oil cyst'], summary: 'A fluid-filled structure that may be discussed when a breast mass is evaluated.', explanation: 'A breast cyst is a fluid-filled structure. A report may use the term when imaging suggests fluid rather than solid tissue. The word alone does not explain a person’s symptoms, diagnosis, or care plan.', questions: ['What features does the report use to describe the cyst?', 'Is the term describing an image finding or a confirmed diagnosis?'], source: 'American Cancer Society — Mammograms', url: 'https://www.cancer.org/cancer/types/breast-cancer/screening-tests-and-early-detection/mammograms.html', reviewed: '2026-11-07' },
  { id: 'fibroadenoma', term: 'Fibroadenoma', clinical: 'A noncancerous breast growth', aliases: ['fibroadenomas', 'benign tumor'], summary: 'A type of noncancerous breast growth that can be mentioned when a mass is evaluated.', explanation: 'A fibroadenoma is a noncancerous breast growth made of fibrous and glandular tissue. If the word appears in a report, the report alone does not tell you how it was identified or what it means for you.', questions: ['Does the report say how this term was determined?', 'Which clinician can explain this term with my other results?'], source: 'National Cancer Institute — Benign & Precancerous Breast Conditions', url: 'https://www.cancer.gov/types/breast/causes-risk-factors/benign-breast-lumps', reviewed: '2026-11-07' },
  { id: 'fat-necrosis', term: 'Fat necrosis', clinical: 'Changed breast fat tissue that may form a lump or scar-like area', aliases: ['fat necrosis', 'necrosis'], summary: 'A noncancerous change in breast fat tissue that can be visible on imaging.', explanation: 'Fat necrosis is a change in breast fat tissue that may form a lump, cyst, or scar-like area. It can occur after injury, surgery, or radiation, but a glossary cannot determine why it appears in any individual report.', questions: ['What location and imaging features does the report describe?', 'What history does my clinician consider when discussing this term?'], source: 'National Cancer Institute — Benign & Precancerous Breast Conditions', url: 'https://www.cancer.gov/types/breast/causes-risk-factors/benign-breast-lumps', reviewed: '2026-11-07' },
  { id: 'oil-cyst', term: 'Oil cyst', clinical: 'A cyst that can form in changed breast fat tissue', aliases: ['oil cysts'], summary: 'A term sometimes used for a cyst associated with changes in breast fat tissue.', explanation: 'An oil cyst can form when breast fat tissue changes. Its presence in a report is an imaging description; the rest of the report and a clinician’s assessment are needed to understand any individual situation.', questions: ['What part of the breast does the report identify?', 'Does the report connect this wording to prior changes or procedures?'], source: 'American Cancer Society — Fat Necrosis and Oil Cysts', url: 'https://www.cancer.org/cancer/types/breast-cancer/non-cancerous-breast-conditions/fat-necrosis-and-oil-cysts-in-the-breast.html', reviewed: '2026-11-07' },
  { id: 'biopsy-clip', term: 'Breast biopsy clip', clinical: 'Small marker placed at a biopsy location', aliases: ['biopsy marker', 'marker clip', 'clip'], summary: 'A small marker that may be left at a biopsy location and seen on future imaging.', explanation: 'A breast biopsy clip is a small marker placed at the site of a biopsy so the location can be recognized on future imaging. Seeing a clip in a report does not, by itself, describe a current diagnosis.', questions: ['Is the report referring to a prior biopsy location?', 'What does the report say about the area around the marker?'], source: 'National Cancer Institute — Breast Biopsy Clip', url: 'https://www.cancer.gov/publications/dictionaries/cancer-terms/def/breast-biopsy-clip', reviewed: '2026-11-07' },
  { id: 'surgical-clips', term: 'Surgical clips', clinical: 'Small markers that may be visible after a breast procedure', aliases: ['surgical clip', 'clips', 'metallic clips'], summary: 'Small markers that can remain visible on imaging after a breast procedure.', explanation: 'Surgical clips are small markers that can be left after a breast procedure and later seen on mammography. The term identifies visible material, not the reason for the procedure or a current diagnosis.', questions: ['Does the report identify the clip location?', 'What prior procedure, if any, does the report mention?'], source: 'National Cancer Institute — Breast Biopsy Clip', url: 'https://www.cancer.gov/publications/dictionaries/cancer-terms/def/breast-biopsy-clip', reviewed: '2026-11-07' },
  { id: 'postsurgical-changes', term: 'Post-surgical changes', clinical: 'Imaging appearance after a breast procedure', aliases: ['postoperative changes', 'post surgical', 'surgical changes', 'scar tissue'], summary: 'A report phrase for an imaging appearance related to a prior breast procedure.', explanation: 'Post-surgical changes describes an imaging appearance that may relate to a prior breast procedure. The phrase does not state which changes are present or what they mean for an individual without the full report and clinical context.', questions: ['Which prior procedure or location does the report mention?', 'Does the report compare this appearance with earlier images?'], source: 'National Cancer Institute — Fat Necrosis', url: 'https://www.cancer.gov/publications/dictionaries/cancer-terms/def/fat-necrosis', reviewed: '2026-11-07' },
  { id: 'cc-view', term: 'CC view', clinical: 'Craniocaudal mammogram image view', aliases: ['cc', 'craniocaudal', 'craniocaudal view'], summary: 'A mammogram image taken from an above-to-below direction.', explanation: 'CC stands for craniocaudal, one standard direction used to take a mammogram image. It labels the image view and does not describe a breast finding.', questions: ['Which breast and image view does the report identify?', 'Is this term being used to describe an image or a finding?'], source: 'FDA — Full-Field Digital Mammography Guidance', url: 'https://www.fda.gov/medical-devices/guidance-documents-medical-devices-and-radiation-emitting-products/full-field-digital-mammography-system-class-ii-special-controls-guidance-industry-and-fda-staff', reviewed: '2026-11-07' },
  { id: 'mlo-view', term: 'MLO view', clinical: 'Mediolateral oblique mammogram image view', aliases: ['mlo', 'mediolateral oblique', 'mediolateral oblique view'], summary: 'A mammogram image taken from an angled side direction.', explanation: 'MLO stands for mediolateral oblique, one standard direction used to take a mammogram image. It labels the image view and does not describe a breast finding.', questions: ['Which breast and image view does the report identify?', 'Is this term being used to describe an image or a finding?'], source: 'FDA — Full-Field Digital Mammography Guidance', url: 'https://www.fda.gov/medical-devices/guidance-documents-medical-devices-and-radiation-emitting-products/full-field-digital-mammography-system-class-ii-special-controls-guidance-industry-and-fda-staff', reviewed: '2026-11-07' },
  { id: 'compression', term: 'Breast compression', clinical: 'Gentle pressure used while mammogram images are made', aliases: ['compression', 'compressed breast'], summary: 'Pressure used during mammography to spread breast tissue for the images.', explanation: 'Breast compression is the pressure used while mammogram images are made. It helps separate overlapping tissue in the image. The term describes the imaging process, not a result.', questions: ['Does the report mention a specific compression view or image?', 'What part of the report describes the finding, if there is one?'], source: 'FDA — Mammography: What You Need to Know', url: 'https://www.fda.gov/consumers/consumer-updates/mammography-what-you-need-know', reviewed: '2026-11-07' },
  { id: 'fibroglandular-tissue', term: 'Fibroglandular tissue', clinical: 'Fibrous and glandular breast tissue', aliases: ['fibroglandular', 'glandular tissue', 'fibrous tissue'], summary: 'Breast tissue made up of fibrous connective tissue and milk-producing glands.', explanation: 'Fibroglandular tissue refers to the fibrous and glandular parts of the breast. Mammogram reports may mention it when describing breast density or the appearance of tissue on the images.', questions: ['Is this term used in the density portion of my report?', 'How does the report describe the tissue appearance?'], source: 'National Cancer Institute — Dense Breasts', url: 'https://www.cancer.gov/types/breast/screening/dense-breasts', reviewed: '2026-11-07' },
  { id: 'fatty-tissue', term: 'Fatty tissue', clinical: 'Fat-containing breast tissue', aliases: ['fatty breasts', 'fatty breast tissue'], summary: 'The fat-containing portion of breast tissue as it appears on a mammogram.', explanation: 'Fatty tissue is the fat-containing portion of the breast as it appears on a mammogram. The phrase may appear in a density description and does not describe body size, health, or a diagnosis.', questions: ['Is this term part of the density description in my report?', 'What other density wording appears with it?'], source: 'National Cancer Institute — Dense Breasts', url: 'https://www.cancer.gov/types/breast/screening/dense-breasts', reviewed: '2026-11-07' },
  { id: 'skin-thickening', term: 'Skin thickening', clinical: 'A description of thicker-appearing breast skin', aliases: ['thickened skin', 'skin changes'], summary: 'A phrase that may describe the appearance of breast skin in an image or report.', explanation: 'Skin thickening describes breast skin that appears thicker than expected in an image or examination note. It is a descriptive phrase, not an explanation of the cause or a diagnosis.', questions: ['Where does the report describe this finding?', 'Which clinician can explain this wording with my full history and images?'], source: 'American Cancer Society — Signs and Symptoms of Breast Cancer', url: 'https://www.cancer.org/cancer/types/breast-cancer/screening-tests-and-early-detection/breast-cancer-signs-and-symptoms.html', reviewed: '2026-11-07' },
  { id: 'nipple-retraction', term: 'Nipple retraction', clinical: 'An inward-pulled nipple appearance', aliases: ['retracted nipple', 'nipple inversion', 'nipple changes'], summary: 'A phrase that may describe a nipple that appears pulled inward.', explanation: 'Nipple retraction describes a nipple that appears pulled inward. Reports can use it as a descriptive observation; the term alone does not establish why it is present or what it means for a particular person.', questions: ['Is the report describing an image observation or a symptom?', 'Who can explain this wording in the context of my care?'], source: 'American Cancer Society — Signs and Symptoms of Breast Cancer', url: 'https://www.cancer.org/cancer/types/breast-cancer/screening-tests-and-early-detection/breast-cancer-signs-and-symptoms.html', reviewed: '2026-11-07' },
  { id: 'axilla', term: 'Axilla', clinical: 'Underarm area near the breast', aliases: ['axillary', 'underarm', 'armpit'], summary: 'The underarm area, where mammogram reports may also describe visible structures.', explanation: 'The axilla is the underarm area beside the breast. A mammogram report may use the word when identifying the location of a lymph node or another observed structure.', questions: ['Does the report identify a structure in the axilla?', 'What location wording appears with this term?'], source: 'American Cancer Society — Understanding Your Mammogram Report', url: 'https://www.cancer.org/cancer/types/breast-cancer/screening-tests-and-early-detection/mammograms/understanding-your-mammogram-report.html', reviewed: '2026-11-07' },
  { id: 'bilateral', term: 'Bilateral', clinical: 'Involving both breasts', aliases: ['both breasts', 'bilaterally'], summary: 'A location word meaning that both breasts are being discussed or imaged.', explanation: 'Bilateral means involving both breasts. It is a location word in a report, not a finding or diagnosis.', questions: ['Which part of the report uses this location term?', 'Does the report describe the same or different observations on each side?'], source: 'National Cancer Institute — Mammograms', url: 'https://www.cancer.gov/types/breast/screening/mammograms', reviewed: '2026-11-07' },
  { id: 'findings', term: 'Findings', clinical: 'The observations described in an imaging report', aliases: ['finding', 'imaging findings'], summary: 'A report section or word used for what the reader observed on the images.', explanation: 'Findings refers to observations described in an imaging report. It may include anatomy, image views, or areas that the reader chose to describe. The word itself is not a diagnosis.', questions: ['Which specific observations are listed under Findings?', 'Where does the report state its overall assessment?'], source: 'FDA — Mammography Information for Patients', url: 'https://www.fda.gov/radiation-emitting-products/mammography-quality-standards-act-mqsa-and-mqsa-program/mammography-information-patients', reviewed: '2026-11-07' },
  { id: 'impression', term: 'Impression', clinical: 'The report’s overall imaging assessment', aliases: ['assessment', 'overall assessment', 'impression section'], summary: 'A report section that brings together the reader’s overall imaging assessment.', explanation: 'Impression is commonly used for the report’s overall imaging assessment. It should be read with the findings and the clinician’s explanation; a glossary cannot determine what an impression means for a specific person.', questions: ['What wording appears in the Impression section?', 'Which clinician can explain it with the rest of my report?'], source: 'FDA — Mammography Information for Patients', url: 'https://www.fda.gov/radiation-emitting-products/mammography-quality-standards-act-mqsa-and-mqsa-program/mammography-information-patients', reviewed: '2026-11-07' },
  { id: 'stable', term: 'Stable', clinical: 'No described change compared with an earlier image', aliases: ['unchanged', 'no interval change', 'stability'], summary: 'A comparison word indicating that an appearance is described as not changing over a stated time.', explanation: 'Stable means the report describes an appearance as not changing compared with the referenced earlier imaging. It is a comparison statement, not a general statement about health or future risk.', questions: ['Which earlier exam is used for the comparison?', 'What specific appearance is described as stable?'], source: 'National Cancer Institute — Mammograms', url: 'https://www.cancer.gov/types/breast/screening/mammograms', reviewed: '2026-11-07' }
];

const categoryNames = { all: 'All terms', assessment: 'Assessments', exam: 'Exams & images', finding: 'Findings', context: 'Context' };
const entryCategories = {
  birads: 'assessment', 'birads-0': 'assessment', 'birads-1': 'assessment', 'birads-2': 'assessment', 'birads-3': 'assessment', 'birads-4': 'assessment', 'birads-5': 'assessment', 'birads-6': 'assessment',
  'screening-mammogram': 'exam', 'diagnostic-mammogram': 'exam', tomosynthesis: 'exam', comparison: 'exam', 'additional-views': 'exam', 'cc-view': 'exam', 'mlo-view': 'exam', compression: 'exam',
  density: 'finding', calcifications: 'finding', mass: 'finding', asymmetry: 'finding', 'architectural-distortion': 'finding', 'lymph-node': 'finding', macrocalcifications: 'finding', microcalcifications: 'finding', cyst: 'finding', fibroadenoma: 'finding', 'fat-necrosis': 'finding', 'oil-cyst': 'finding', 'fibroglandular-tissue': 'finding', 'fatty-tissue': 'finding', 'skin-thickening': 'finding', 'nipple-retraction': 'finding', axilla: 'finding', stable: 'finding',
  'breast-implant': 'context', 'biopsy-clip': 'context', 'surgical-clips': 'context', 'postsurgical-changes': 'context', bilateral: 'context', findings: 'context', impression: 'context'
};

const $ = (selector) => document.querySelector(selector);
const search = $('#search');
const resultList = $('#resultsList');
const topicGrid = $('#topicGrid');
const resultMeta = $('#resultMeta');
const entryDialog = $('#entryDialog');
const sourcesDialog = $('#sourcesDialog');
let bookmarks = [];
let storageAvailable = true;
let feedbackTimer;
let updateReady = false;
let dialogOpener = null;
let activeCategory = 'all';

try {
  const stored = JSON.parse(localStorage.getItem('mammogram-bookmarks') || '[]');
  bookmarks = Array.isArray(stored) ? stored.filter((bookmark) => entries.some((entry) => entry.id === bookmark?.entry_id)) : [];
} catch { storageAvailable = false; }

function persist() { try { localStorage.setItem('mammogram-bookmarks', JSON.stringify(bookmarks)); } catch { storageAvailable = false; } }
function isSaved(id) { return bookmarks.some((bookmark) => bookmark.entry_id === id); }
function focusOpener() {
  const opener = dialogOpener;
  dialogOpener = null;
  setTimeout(() => opener?.focus?.(), 0);
}

function externalLink(url, text) {
  const link = document.createElement('a');
  link.href = url;
  link.target = '_blank';
  link.rel = 'noopener noreferrer';
  link.textContent = `${text} ↗`;
  return link;
}

function renderCard(entry) {
  const fragment = $('#entryTemplate').content.cloneNode(true);
  const card = fragment.querySelector('.entry-card');
  card.dataset.id = entry.id;
  const open = fragment.querySelector('.entry-open');
  open.textContent = entry.term;
  open.addEventListener('click', () => openEntry(entry.id, open));
  fragment.querySelector('.entry-summary').textContent = entry.summary;
  const bookmark = fragment.querySelector('.bookmark-button');
  bookmark.textContent = isSaved(entry.id) ? '★' : '☆';
  bookmark.setAttribute('aria-label', `${isSaved(entry.id) ? 'Remove' : 'Save'} ${entry.term}`);
  bookmark.setAttribute('aria-pressed', String(isSaved(entry.id)));
  bookmark.addEventListener('click', () => toggleBookmark(entry.id));
  return fragment;
}

function runSearch() {
  const query = search.value.trim().toLowerCase();
  resultList.replaceChildren();
  $('#clearSearch').hidden = !query;
  $('#searchAgain').hidden = !query;
  topicGrid.querySelectorAll('[data-category]').forEach((button) => button.setAttribute('aria-pressed', String(button.dataset.category === activeCategory)));
  const found = entries.filter((entry) => (activeCategory === 'all' || entryCategories[entry.id] === activeCategory) && [entry.term, entry.clinical, ...entry.aliases, entry.summary].join(' ').toLowerCase().includes(query));
  const scope = categoryNames[activeCategory];
  resultMeta.textContent = query ? `${scope} · “${search.value.trim()}” · ${found.length} ${found.length === 1 ? 'entry' : 'entries'}` : `${scope} · ${found.length} ${found.length === 1 ? 'entry' : 'entries'}`;
  if (!found.length) {
    resultList.innerHTML = '<div class="empty-state"><h3>No term found yet</h3><p>Try a shorter term, “BI-RADS,” “density,” or a different spelling. This search stays on your device; please don’t include report text or personal information.</p></div>';
    return;
  }
  found.forEach((entry) => resultList.append(renderCard(entry)));
}

function openEntry(id, opener = document.activeElement) {
  const entry = entries.find((item) => item.id === id);
  if (!entry) return;
  dialogOpener = opener;
  const content = document.createElement('div');
  content.className = 'dialog-body';
  const title = document.createElement('h2'); title.id = 'dialogTitle'; title.textContent = entry.term;
  const clinical = document.createElement('p'); clinical.className = 'clinical-name'; clinical.textContent = entry.clinical;
  const explanation = document.createElement('p'); explanation.textContent = entry.explanation;
  const heading = document.createElement('h3'); heading.textContent = 'What to ask your clinician';
  const questions = document.createElement('ul'); questions.className = 'question-list';
  entry.questions.forEach((question) => { const item = document.createElement('li'); item.textContent = question; questions.append(item); });
  const source = document.createElement('div'); source.className = 'source-block';
  if (!navigator.onLine) { const offline = document.createElement('span'); offline.className = 'offline-tag'; offline.textContent = 'External link needs connection'; source.append(offline); }
  source.append('Source: ', externalLink(entry.url, entry.source));
  content.append(title, clinical, explanation, heading, questions, source);
  $('#entryContent').replaceChildren(content);
  entryDialog.showModal();
}

function announce(message) { $('#saveFeedback').textContent = message; clearTimeout(feedbackTimer); feedbackTimer = setTimeout(() => { $('#saveFeedback').textContent = ''; }, 4000); }

function toggleBookmark(id) {
  const entry = entries.find((item) => item.id === id);
  if (!entry) return;
  const removed = isSaved(id);
  if (removed) bookmarks = bookmarks.filter((bookmark) => bookmark.entry_id !== id);
  else if (storageAvailable) bookmarks.push({ entry_id: id, saved_at: new Date().toISOString() });
  persist(); renderBookmarks(); runSearch();
  const activeList = location.hash === '#bookmarks' ? $('#bookmarksList') : resultList;
  const replacement = activeList.querySelector(`[data-id="${id}"] .bookmark-button`);
  (replacement || (location.hash === '#bookmarks' ? $('#saved-title') : $('#clearSearch'))).focus();
  announce(storageAvailable ? `${entry.term} ${removed ? 'removed from saved terms' : 'saved on this device'}.` : 'Bookmarks could not be saved in this browser.');
}

function renderBookmarks() {
  const saved = entries.filter((entry) => isSaved(entry.id));
  const list = $('#bookmarksList'); list.replaceChildren();
  document.querySelectorAll('.saved-count').forEach((count) => { count.textContent = saved.length; count.setAttribute('aria-label', `${saved.length} saved ${saved.length === 1 ? 'term' : 'terms'}`); });
  $('#clearBookmarks').hidden = !saved.length;
  if (!storageAvailable) { list.innerHTML = '<div class="saved-message"><strong>Bookmarks aren’t available in this browser.</strong><br />You can still read and search the glossary. This can happen when browser storage is unavailable or was cleared.</div>'; return; }
  if (!saved.length) { list.innerHTML = '<div class="saved-message"><strong>Nothing saved yet.</strong><br />Use the star on a glossary entry to keep it here on this device.</div>'; return; }
  saved.forEach((entry) => list.append(renderCard(entry)));
}

function updateConnection() {
  const status = $('#connectionStatus');
  const messages = [];
  if (!navigator.onLine) messages.push('You’re offline. Glossary content and saved terms are available; external source links need a connection.');
  if (updateReady) messages.push('A content update is ready. Reload the app to use the latest library.');
  status.hidden = messages.length === 0;
  $('#connectionMessage').textContent = messages.join(' ');
  $('#reloadApp').hidden = !updateReady;
}
function showUpdate() { updateReady = true; updateConnection(); }
function showScreen(moveFocus = false) {
  const saved = location.hash === '#bookmarks', browsing = location.hash === '#browse', about = location.hash === '#help', home = !saved && !browsing && !about;
  document.body.classList.toggle('home-screen', home);
  $('#home').hidden = !home; $('#browse').hidden = !browsing; $('#help').hidden = !about; $('#bookmarks').hidden = !saved;
  document.querySelector('nav a[href="#home"]').setAttribute('aria-current', home ? 'page' : 'false');
  document.querySelector('nav a[href="#bookmarks"]').setAttribute('aria-current', saved ? 'page' : 'false');
  document.querySelector('nav a[href="#browse"]').setAttribute('aria-current', browsing ? 'page' : 'false');
  document.querySelector('nav a[href="#help"]').setAttribute('aria-current', about ? 'page' : 'false');
  window.scrollTo(0, 0);
  if (moveFocus) $(saved ? '#saved-title' : browsing ? '#results-title' : about ? '#help-title' : '#hero-title').focus({ preventScroll: true });
}

$('#searchButton').addEventListener('click', () => { activeCategory = 'all'; runSearch(); location.hash = '#browse'; });
search.addEventListener('keydown', (event) => { if (event.key === 'Enter') { event.preventDefault(); activeCategory = 'all'; runSearch(); location.hash = '#browse'; } });
document.querySelector('nav a[href="#browse"]').addEventListener('click', runSearch);
$('#clearSearch').addEventListener('click', () => { search.value = ''; activeCategory = 'all'; runSearch(); topicGrid.querySelector('[data-category="all"]').focus(); });
$('#searchAgain').addEventListener('click', () => setTimeout(() => search.focus(), 0));
document.querySelectorAll('[data-home-search]').forEach((button) => button.addEventListener('click', () => { location.hash = '#home'; setTimeout(() => search.focus(), 0); }));
document.querySelectorAll('[data-search]').forEach((button) => button.addEventListener('click', () => { search.value = button.dataset.search; activeCategory = 'all'; runSearch(); location.hash = '#browse'; }));
topicGrid.querySelectorAll('[data-category]').forEach((button) => button.addEventListener('click', () => { search.value = ''; activeCategory = button.dataset.category; runSearch(); }));
$('#clearBookmarks').addEventListener('click', () => { if (confirm('Clear all saved terms from this device?')) { bookmarks = []; persist(); renderBookmarks(); runSearch(); announce('All saved terms were removed from this device.'); } });
$('#closeDialog').addEventListener('click', () => entryDialog.close());
entryDialog.addEventListener('click', (event) => { if (event.target === entryDialog) entryDialog.close(); });
entryDialog.addEventListener('close', focusOpener);
$('#openSources').addEventListener('click', (event) => { dialogOpener = event.currentTarget; sourcesDialog.showModal(); });
$('#closeSources').addEventListener('click', () => sourcesDialog.close());
sourcesDialog.addEventListener('click', (event) => { if (event.target === sourcesDialog) sourcesDialog.close(); });
sourcesDialog.addEventListener('close', focusOpener);
$('#reloadApp').addEventListener('click', () => location.reload());
window.addEventListener('online', updateConnection); window.addEventListener('offline', updateConnection); window.addEventListener('hashchange', () => showScreen(true));
updateConnection(); renderBookmarks(); runSearch(); showScreen();
if ('serviceWorker' in navigator) navigator.serviceWorker.register('./sw.js').then((registration) => { if (registration.waiting) showUpdate(); registration.addEventListener('updatefound', () => { const worker = registration.installing; worker?.addEventListener('statechange', () => { if (worker.state === 'installed' && navigator.serviceWorker.controller) showUpdate(); }); }); }).catch(() => {});

window.MammoLingo = { entries, runSearch, openEntry, toggleBookmark, renderBookmarks };
